  }, [active, account, base]);

  const value = useMemo<Sync>(
    () =>
      available
        ? {
            available,
            enabled,
            setEnabled: (on) => {
              setSyncEnabled(on);
              setEnabledState(on);
            },
            status: active ? status : "off",
