1	// @vitest-environment jsdom
2	import { readFileSync } from "node:fs";
3	import { dirname, join } from "node:path";
4	import { fileURLToPath } from "node:url";
5	import { afterEach, describe, expect, it, vi } from "vitest";
6	import { act, cleanup, render, screen } from "@testing-library/react";
7	import { loadPackText } from "@runlog/rules-schema";
8	import type { RunEvent } from "@runlog/engine";
9	import type { Api } from "../sync/client.ts";
10	import { heldMove, perRacer, RunView } from "./RunView.tsx";
11	import { memoryRunStore } from "./store.ts";
12	import { syncBus } from "../sync/bus.ts";
13	import { SyncContext, type Sync } from "../sync/SyncProvider.tsx";
14	
15	/**
16	 * The offer rides along with the snapshot.
17	 *
18	 * `RunView` publishes to the server through `useApi()`, a hook rather than a
19	 * prop, so it is mocked module-wide the way `ChatPanel.test.tsx` mocks it.
20	 * The run itself is a real, hydrated one-event log in a memory store: the
21	 * engine's own `reduce` has to accept it, so this is the shortest log that
22	 * does. `bench` keeps the race, asks and members panels off the tree; none
23	 * of the three touch the offer, and each would otherwise want its own slice
24	 * of the API double.
25	 */
26	
27	const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "..");
28	const loaded = loadPackText(readFileSync(join(repoRoot, "packs/demo/pack.yaml"), "utf8"), "yaml");
29	if (!loaded.ok) throw new Error("the demo pack did not load");
30	const kiln = loaded.pack;
31	const mode = Object.keys(kiln.modes)[0]!;
32	
33	const current: { api: Api | null } = { api: null };
34	vi.mock("../sync/useApi.ts", () => ({ useApi: () => current.api }));
35	
36	afterEach(() => {
37	  current.api = null;
38	  cleanup();
39	  vi.useRealTimers();
40	});
41	
42	/** A handful of microtask turns: enough for the store's promise chain to settle. */
43	async function flush(turns = 6) {
44	  for (let i = 0; i < turns; i++) {
45	    // eslint-disable-next-line no-await-in-loop
46	    await act(async () => {
47	      await Promise.resolve();
48	    });
49	  }
50	}
51	
52	/**
53	 * The rest of a log that lands on the pack's one checklist step: into the
54	 * first Stage, past the manual step that opens it, and past the declared
55	 * Piece. The Kiln Check and the Constraint are both skipped in Stage 1 by
56	 * the pack's own rules, so "Throw it." and its checklist come next.
57	 */
58	const toTheChecklist = (at: string) => [
59	  { id: "e2", t: "UnitEntered" as const, at },
60	  { id: "e3", t: "StepCompleted" as const, at, phase: "enter", step: 0 },
61	  { id: "e4", t: "PhaseCompleted" as const, at, phase: "enter" },
62	  { id: "e5", t: "SubjectDeclared" as const, at, subjectType: "bowl" },
63	  { id: "e6", t: "StepCompleted" as const, at, phase: "declare", step: 0 },
64	  { id: "e7", t: "PhaseCompleted" as const, at, phase: "declare" },
65	];
66	
67	/**
68	 * Sync, as a press needs it: the socket is not here, so `drove` is a spy
69	 * and everything else is the off value the app itself falls back to.
70	 */
71	const syncWith = (drove: Sync["drove"]): Sync => ({
72	  available: true,
73	  enabled: true,
74	  setEnabled: () => {},
75	  status: "idle",
76	  last: null,
77	  syncNow: () => {},
78	  setPackSync: async () => {},
79	  gesture: () => false,
80	  drove,
81	});
82	
83	async function renderRunView({
84	  putSnapshot,
85	  shared,
86	  decksAttached = 0,
87	  rest = () => [],
88	  drove = () => {},
89	}: {
90	  putSnapshot: Api["putSnapshot"];
91	  shared: boolean;
92	  decksAttached?: number;
93	  /** What the run has done since it started, for a test that needs a step. */
94	  rest?: (at: string) => RunEvent[];
95	  /** The verdict this device sends back, for the tests about pressing. */
96	  drove?: Sync["drove"];
97	}) {
98	  current.api = { putSnapshot, myRaces: async () => [] } as unknown as Api;
99	  const store = memoryRunStore();
100	  const runId = "run1";
101	  const at = "2026-09-14T00:00:00.000Z";
102	  const events = [
103	    { id: "e1", t: "RunStarted" as const, at, packId: kiln.id, packVersion: kiln.version, runId, mode },
104	    ...rest(at),
105	  ] as RunEvent[];
106	  await store.saveRun({
107	    runId,
108	    packId: kiln.id,
109	    packVersion: kiln.version,
110	    packTitle: kiln.title,
111	    events,
112	    updatedAt: at,
113	    role: "player",
114	    shared,
115	  });
116	  store.setActiveRunFor(kiln.id, runId);
117	
118	  // Fake timers are on before the first render, so the debounce's own
119	  // setTimeout is one this test can wind forward rather than a real one
120	  // already ticking by the time it asks.
121	  vi.useFakeTimers();
122	  render(
123	    <SyncContext.Provider value={syncWith(drove)}>
124	      <RunView pack={kiln} store={store} bench={{ from: "test", onLeave: () => {} }} />
125	    </SyncContext.Provider>,
126	  );
127	  await flush();
128	
129	  if (decksAttached > 0) {
130	    act(() => {
131	      syncBus.emit({ t: "gesture", id: runId, kind: "tools", data: { tools: [], count: 0, decks: decksAttached }, at });
132	    });
133	  }
134	}
135	
136	describe("the offer rides along with the snapshot", () => {
137	  it("publishes an offer beside the snapshot", async () => {
138	    const putSnapshot = vi.fn<Api["putSnapshot"]>(async () => {});
