1	/**
2	 * Which run this device has open.
3	 *
4	 * Per pack, the run that Play shows for it; and overall, the run this
5	 * device touched last, which is the one to return to and the one another
6	 * device with nothing open should start from. Both live in localStorage
7	 * beside the sync switch: they are facts about this device, not about the
8	 * account, and they must survive a reload but never travel.
9	 *
10	 * Nothing here clears itself. Browsing another pack, the profile, or
11	 * Inspect leaves the active run where it was; only starting another,
12	 * switching, or discarding moves it.
13	 */
14	
15	const PER_PACK = "runlog:active:";
16	const LAST = "runlog:active";
17	
18	/**
19	 * Stored in a pack's slot when the player asked for a fresh run and has not
20	 * started it: setup shows, and nothing arriving from elsewhere fills it.
21	 */
22	export const NEW_RUN = "new";
23	
24	export interface LastActive {
25	  packId: string;
26	  runId: string;
27	}
28	
29	function storage(): Storage | null {
30	  try {
31	    return typeof localStorage === "undefined" ? null : localStorage;
32	  } catch {
33	    return null;
34	  }
35	}
36	
37	/** The run open for this pack on this device, if one was chosen. */
38	export function activeRunFor(packId: string): string | null {
39	  return storage()?.getItem(PER_PACK + packId) ?? null;
