1	import { appBase, hrefFor, PATHS_ON } from "../route.ts";
2	import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
3	// The badge and menu are in AccountBadge.tsx: they read sync's context too,
4	// and sync's provider reads this one.
5	import { createClient, type User } from "@workos-inc/authkit-js";
6	import { honestAddress } from "../welcome/route.ts";
7	import { appUrl, configuredClientId } from "./config.ts";
8	import { whoIsHere } from "../storage/who.ts";
9	
10	/**
11	 * Who is here, if anyone.
12	 *
13	 * The app never needs an account: everything it does happens on this machine,
14	 * and a copy on disk or on a public page has nobody to sign in with. Where a
15	 * build does know an AuthKit client, signing in is an offer in the header, not
16	 * a door, it unlocks what a server adds (sync, on by default once you have
17	 * signed in; a switch on this device turns it off) and gates nothing.
18	 * The first paint is always the app; WorkOS is asked in the background.
19	 *
20	 * The SDK does the awkward part: it notices the `?code=` AuthKit sends back,
21	 * exchanges it, tidies the URL, and keeps the session alive. This only has to
22	 * report what that ended with, and hand out a token when something asks.
23	 */
24	
25	export type Account =
26	  /** Nothing to sign into: no client configured. Disk, Pages, the tests. */
27	  | { status: "local" }
28	  /** A session may exist; WorkOS is being asked. Sign-in queues behind it. */
29	  | { status: "checking"; signIn: () => void }
30	  /** `signUp` lands on AuthKit's create-an-account screen; the same door, the other sign. */
31	  | { status: "anonymous"; signIn: () => void; signUp: () => void; problem?: string }
32	  | {
33	      status: "signed-in";
34	      user: User;
35	      signOut: () => void;
36	      /** A fresh access token, refreshed by the SDK when it has to be. */
37	      getAccessToken: () => Promise<string>;
38	    };
